import{_ as t,o,c as s,a2 as d}from"./chunks/framework.C8nVztS1.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common errors, env flags, and untestutils doctor.","frontmatter":{"title":"Troubleshooting","description":"Common errors, env flags, and untestutils doctor.","outline":"deep"},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1789828988000}'),r={name:"guide/troubleshooting.md"};function i(a,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> untestutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> untestutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recipes</span></span></code></pre></div><p>Checks Node, peers (Vitest major 4|5), configs, and <code>recipes.ts</code>. <code>doctor --recipes</code> lists registered ids.</p><h2 id="common-errors" tabindex="-1">Common errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common errors&quot;">​</a></h2><p><strong>unknown recipe id</strong> — <code>defineRecipes({ … }, import.meta.url)</code> and pass <code>recipes</code> into the plugin so workers re-import the module. Error messages list <strong>known ids</strong> when the registry is loaded.</p><p><strong>prewarm id not found</strong> — same: id must exist in the recipes module; message lists known ids.</p><p><strong>no harness url</strong> — call <code>useHarness</code> or list the id in <code>prewarm</code> before using <code>page</code> / <code>baseURL</code>.</p><p><strong>Playwright picked up <code>*.test.ts</code></strong> — <code>createPlaywrightConfig</code> defaults to <code>testMatch: &#39;**/*.spec.ts&#39;</code>. Override via <code>testMatch</code> if needed.</p><p><strong>Config pulled in fixtures</strong> — use <code>untestutils/vitest/plugin</code> in config, not <code>untestutils/vitest</code>.</p><p><strong>Ready hang / readiness failed</strong> — local servers bind <code>ctx.host</code> (default <code>127.0.0.1</code>, override with <code>UNTESTUTILS_BIND_HOST</code>). Ready probes TCP then HTTP; wildcard binds like <code>0.0.0.0</code> still probe <code>127.0.0.1</code>. For <code>host()</code>, set <code>readyTimeoutMs</code> / <code>readyPath</code>, or <code>skipReady: true</code> if the URL is already up. Drivers that wait inside <code>start</code> use a noop <code>ready</code> so the orchestrator does not probe twice.</p><p><strong>Orphan processes</strong> — hard-killed runs leave locks; clear <code>.untestutils</code> and retry. Teardown must not kill pid ≤ 1.</p><p><strong>Empty setup / recipes never load</strong> — published facade must keep <code>vitest/setup-file</code> side effects (re-export, not a dead <code>await import</code>). Upgrade to a release that includes that fix.</p><h2 id="env" tabindex="-1">Env <a class="header-anchor" href="#env" aria-label="Permalink to &quot;Env&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>UNTESTUTILS_DEBUG=1</code></td><td>Verbose logs</td></tr><tr><td><code>UNTESTUTILS_QUIET=1</code> / <code>PROGRESS=0</code></td><td>Silence progress</td></tr><tr><td><code>UNTESTUTILS_SHARE=0</code></td><td>Disable share</td></tr><tr><td><code>UNTESTUTILS_ARTIFACTS_DIR</code></td><td>Custom artifacts root</td></tr><tr><td><code>UNTESTUTILS_BIND_HOST</code></td><td>Bind/probe host for local servers (default <code>127.0.0.1</code>; <code>localhost</code>/<code>::1</code> coerced to IPv4)</td></tr><tr><td><code>UNTESTUTILS_REMOTE_URL</code></td><td>Remote <code>host()</code> URL</td></tr><tr><td><code>UNTESTUTILS_BROWSER</code></td><td>Playwright engine for Vitest fixtures</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/untestutils/guide/getting-started">Getting started</a></li><li><a href="/untestutils/guide/how-it-works">How it works</a></li><li><a href="/untestutils/cli/">CLI</a></li></ul>`,16)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
